8:         function createLayoutCache(maxGroups = 8, maxNodes = 2000) {
9:             const entries = new Map();
10:             function signature(nodes, links) {
11:                 return JSON.stringify([
12:                     nodes.map(n => n.id).sort(),
13:                     links.map(l => JSON.stringify([l.sourceId, l.targetId, l.verb])).sort()
14:                 ]);
15:             }
16:             return {
17:                 get(key, nodes, links) {
18:                     const entry = entries.get(key);
19:                     if (!entry || entry.signature !== signature(nodes, links)) return null;
20:                     entries.delete(key);
21:                     entries.set(key, entry);
22:                     return entry;
23:                 },
24:                 set(key, nodes, links, transform, state = { settled: true, alpha: 0, autoFit: false }) {
25:                     entries.delete(key);
26:                     if (nodes.length > maxNodes || links.length > maxNodes * 8 || !nodes.every(n => Number.isFinite(n.x) && Number.isFinite(n.y))) return;
27:                     entries.set(key, {
28:                         signature: signature(nodes, links),
29:                         positions: new Map(nodes.map(n => [n.id, { x: n.x, y: n.y }])),
30:                         transform: { x: transform.x, y: transform.y, k: transform.k },
31:                         settled: state.settled,
32:                         alpha: state.alpha,
33:                         autoFit: state.autoFit
34:                     });
35:                     let count = [...entries.values()].reduce((sum, entry) => sum + entry.positions.size, 0);
36:                     while (entries.size > maxGroups || count > maxNodes) {
37:                         const oldest = entries.keys().next().value;
38:                         count -= entries.get(oldest).positions.size;
39:                         entries.delete(oldest);
40:                     }
41:                 },
42:                 clear() { entries.clear(); }
43:             };
44:         }
