48:         function createStaticLayout(sim, render, complete, failed) {
49:             let frame = 0;
50:             let ticks = 0;
51:             let elapsed = 0;
52:             let done = false;
53:             sim.stop().alphaTarget(0).alphaDecay(0.08);
54:             function step() {
55:                 frame = 0;
56:                 const start = performance.now();
57:                 try {
58:                     do {
59:                         sim.tick();
60:                         ticks++;
61:                     } while (ticks < 120 && sim.alpha() > sim.alphaMin() && performance.now() - start < 6);
62:                     render();
