78:                 if (!done && !frame && !document.hidden) frame = requestAnimationFrame(step);
79:             }
80:             function pause() {
81:                 if (frame) cancelAnimationFrame(frame);
82:                 frame = 0;
83:             }
84:             return {
85:                 resume,
86:                 pause,
87:                 stop() { done = true; pause(); sim.stop(); }
