2011:         function renderObservations(entity) {
2012:             const observations = entity.observations || [];
2013:             const total = entity.observationCount || observations.length || 0;
2014: 
2015:             if (!total) {
2016:                 return '';
2017:             }
2018: 
2019:             let html = '<div class="obs-section">';
2020:             html += \`<div class="obs-title">\${i18n.tooltip.observations}\${total ? ' (' + total + ')' : ''}</div>\`;
2021: 
2022:             const maxItems = 3;
2023:             const visible = observations.slice(0, maxItems);
2024: 
2025:             html += '<ul class="obs-list">';
2026:             visible.forEach(item => {
2027:                 html += \`<li>\${escapeHtml(item.content || '')}</li>\`;
2028:             });
2029:             html += '</ul>';
2030: 
2031:             const remaining = Math.max(total - visible.length, 0);
2032:             if (remaining > 0) {
2033:                 html += \`<div class="obs-more">\${i18n.tooltip.more.replace('{count}', remaining)}</div>\`;
2034:             }
2035: 
2036:             html += '</div>';
