2045:                 .replace(/&/g, '&amp;')
2046:                 .replace(/</g, '&lt;')
2047:                 .replace(/>/g, '&gt;')
2048:                 .replace(/"/g, '&quot;')
2049:                 .replace(/'/g, '&#39;')
2050:                 .replace(/\\n/g, '<br>');
