2053:         function fitGraph() {
2054:             if (!g) return;
2055:             
2056:             // Use D3 zoom to fit
2057:             const bounds = g.node().getBBox();
2058:             const parent = svg.node().parentElement;
2059:             const fullWidth = parent.clientWidth;
2060:             const fullHeight = parent.clientHeight;
2061:             
2062:             const width = bounds.width;
2063:             const height = bounds.height;
2064:             
2065:             if (width === 0 || height === 0 || fullWidth === 0 || fullHeight === 0) return;
2066:             
2067:             const midX = bounds.x + width / 2;
2068:             const midY = bounds.y + height / 2;
2069:             
2070:             const scale = Math.max(0.1, Math.min(4, 0.85 / Math.max(width / fullWidth, height / fullHeight)));
2071:             const translate = [fullWidth / 2 - scale * midX, fullHeight / 2 - scale * midY];
2072:             
2073:             (performanceMode === 'low' ? svg.interrupt() : svg.transition().duration(750))
2074:                 .call(zoom.transform, d3.zoomIdentity.translate(translate[0], translate[1]).scale(scale));
2075:         }
